async function ensure(){if(!db)throw Error("storage_unconfigured");await db.unsafe("CREATE TABLE IF NOT EXISTS early_access (id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL, country TEXT NOT NULL, interest TEXT NOT NULL, consent BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await db.unsafe("CREATE TABLE IF NOT EXISTS privacy_requests (id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL, kind TEXT NOT NULL, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())")}

